// 1. Safely fetch history rows (filters out empty results when DB has 0 rows)
let historyItems = [];
try {
  historyItems = $('Execute a SQL query')
    .all()
    .map(item => item.json)
    .filter(row => row && Object.keys(row).length > 0 && row.turn_index !== undefined);
} catch (e) {
  historyItems = [];
}

// 2. Safely detect which trigger ran (Chat Trigger vs Webhook)
let currentMessage = '';
let caseId = 'case_001';

try {
  const chatData = $('When chat message received').first().json;
  currentMessage = chatData.chatInput || chatData.message || '';
  caseId = chatData.case_id || chatData.sessionId || 'case_001';
} catch (e) {
  try {
    const webhookData = $('Webhook').first().json;
    const body = webhookData.body || webhookData;
    currentMessage = body.message || '';
    caseId = body.case_id || 'case_001';
  } catch (err) {
    try {
      const execData = $('Execute Workflow Trigger').first().json;
      currentMessage = execData.message || execData.player_message || '';
      caseId = execData.case_id || 'case_001';
    } catch (finalErr) {}
  }
}

// 3. Format history with clean handling for 0 previous turns
let formattedHistory = '';

if (historyItems.length === 0) {
  formattedHistory = 'No previous interactions. This is the very beginning of the investigation (Turn 1).';
} else {
  // Split: Last 3 turns get full content, older turns get summary
  const splitIndex = Math.max(0, historyItems.length - 3);
  const olderTurns = historyItems.slice(0, splitIndex);
  const recentTurns = historyItems.slice(splitIndex);

  const timelineParts = [];

  // Older turns (summary only)
  for (const row of olderTurns) {
    const idx = row.turn_index;
    const agent = String(row.agent || '').toUpperCase();
    const summary = row.summary || 'No summary available.';
    timelineParts.push(`[Turn ${idx} - ${agent} SUMMARY]: ${summary}`);
  }

  // Recent 3 turns (full content)
  for (const row of recentTurns) {
    const idx = row.turn_index;
    const agent = String(row.agent || '').toUpperCase();
    const playerMsg = row.player_message || '';
    const replyContent = row.content || row.summary || '';

    timelineParts.push(
      `[Turn ${idx} - ${agent}]\nPlayer asked: "${playerMsg}"\nAgent reply: "${replyContent}"`
    );
  }

  formattedHistory = timelineParts.join('\n\n');
}

// 4. Construct the prompt
const fullPrompt = `<case_history>
${formattedHistory}
</case_history>

<player_message>
${currentMessage}
</player_message>`;

return [
  {
    json: {
      case_id: caseId,
      player_message: currentMessage,
      formatted_history: formattedHistory,
      full_prompt: fullPrompt
    }
  }
];

