  },
  {
    "doc_id": "bh-05",
    "case_id": "blue_horses_dusk",
    "document_type": "comparanda",
    "title": "Heinrich Moll: career summary (game-world reference)",
    "text": "Heinrich Moll was a German painter born in the Rhineland in the 1880s who moved in Rhineland and Munich circles in the 1910s. He painted animals, landscapes and figures in bold, simplified forms, and his work is usually discussed in relation to the Blue Rider generation, though he was never a formal member of the group. Around thirty oil paintings are securely attributed to him. His output was reduced by war service and by later hostility to modern art, and he died in the 1950s. He is a lesser-known figure, and attributions of his work rely largely on comparison with a small securely attributed group."
  },
  {
    "doc_id": "bh-06",
    "case_id": "blue_horses_dusk",
    "document_type": "secondary_description",
    "title": "Blue Horses at Dusk: subject and composition",
    "text": "Blue Horses at Dusk is a mid-sized oil painting attributed to Heinrich Moll and described as belonging to his Rhineland expressionist period. Three horses overlap in profile in the foreground of a hilly landscape at dusk. Their bodies are simplified into curving, outlined shapes in deep blue and violet, with accents of red and yellow-green. The hills behind them are broken into angular, overlapping planes and the sky is banded in cool tones. The composition is flattened, with little perspective, and the strong outlines and colour contrasts place the picture in the manner of the Blue Rider generation."
  }
];

// Instantly split into 19 individual items for Chroma
return docs.map(doc => ({ json: doc }));

// Decodes binary CSV data to text
const csvText = Buffer.from($binary.data.data, 'base64').toString('utf-8');

const lines = csvText.trim().split(/\r?\n/);
const headers = lines[0].split(',').map(h => h.trim());

return lines.slice(1).map(line => {
  const values = line.split(',').map(v => v.trim());
  const row = {};
  headers.forEach((header, i) => row[header] = values[i] || '');
  return row;
});
